        let mut i: isize = 15;
        while i >= 0 && buf[i as usize] == b'Z' {
            buf[i as usize] = b'0';
            i -= 1;
        }

        if i < 0 {
            /* restart 1ms + a bit later */
            std::thread::sleep(std::time::Duration::from_nanos(1_234_567));
            ulidgen_r(ulid);
            return;
        }

        let i = i as usize;
        if let Some(pos) = B32_ALPHABET.iter().position(|&c| c == buf[i]) {
